/* selectMasterMdCmStndCatalogRegList */ SELECT SEQ, CMS_CATLG_ID, CATL.CMS_CATEG_ID, (SELECT CATEG.CATEG_NAME FROM CMSCATEG CATEG WHERE CATEG.CMS_CATEG_ID =CATL.CMS_CATEG_ID) AS CMS_CATEG_NAME, DECODE(STATUS,'S','미생성','P','품의상신','B','반려','승인') AS STATUS, CATL.STATUS AS STATUS_CD, DESCRIPTION_LOC, DESCRIPTION_ENG, REP_SEPCIFICATION, SPECIFICATION, MAKER_CODE, DECODE(CATL.MAKER_CODE, '',CATL.MAKER_NAME ,(SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'M104' AND COD.CODE =CATL.MAKER_CODE)) AS MAKER_NAME, ORIGIN_CODE, ORDER_MEASURE, STD_FLAG, REMARK, KEP_DEPT, STOCK_GROUP_TYPE, MODEL_INFO, STATUS AS STATUS_CD, DETAIL_IMGFILE_NAME, DETAIL_IMGFILE_DIR, IMGFILE_NAME, IMGFILE_DIR, PM_NO, PM_SEQ, ITEM_GUBUN, SPECIFICATION_ENG FROM CMSCATLG_ADD CATL WHERE CATL.ADD_USER_ID = #{st_user_id} AND CATL.ADD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND CATL.DESCRIPTION_LOC LIKE '%' || #{st_description_loc} || '%'
AND CATL.SPECIFICATION LIKE '%' || #{st_sepcification} || '%'
AND CATL.STATUS = #{st_status}
ORDER BY SEQ

mapper.update:
SELECT TO_NUMBER(SUBSTR(MAX(CMS_CATLG_ID),2,9))+1 AS MAX_CMS FROM CMSCATLG
/* insertMasterMdCmStndCatalogReg */ INSERT INTO CMSCATLG (CMS_CATLG_ID, CMS_CATEG_ID, STATUS, DESCRIPTION_LOC, DESCRIPTION_ENG, REP_SEPCIFICATION, SPECIFICATION, MAKER_CODE, MAKER_NAME, ORIGIN_CODE, ORDER_MEASURE, ATTB1_NM, ATTB2_NM, ATTB3_NM, ATTB4_NM, ATTB5_NM, ATTB6_NM, ATTB7_NM, ATTB8_NM, ATTB9_NM, ATTB10_NM, ATTB11_NM, ATTB12_NM, ATTB13_NM, ATTB14_NM, ATTB15_NM, ATTB16_NM, ATTB17_NM, ATTB18_NM, ATTB19_NM, ATTB20_NM, DELIVERY_LT, ITEM_GUBUN, ITEM_GROUP, ONOFF_TYPE, STD_FLAG, IMG_NO, IMG_FLAG, IMAGE_KEY, REMARK, ADD_DATE, ADD_TIME, ADD_USER_ID, CHANGE_DATE, CHANGE_TIME, CHANGE_USER_ID, CMS_PRICE, KEP_DEPT, STOCK_GROUP_TYPE, DETAIL_IMGFILE_NAME, DETAIL_IMGFILE_DIR, IMGFILE_NAME, IMGFILE_DIR, MODEL_INFO
) SELECT 'M' || LPAD (#{MAX_CMS}, 9, 0) AS CMS_CATLG_ID, CMS_CATEG_ID, 'S', DESCRIPTION_LOC, DESCRIPTION_ENG, REP_SEPCIFICATION, SPECIFICATION, MAKER_CODE, MAKER_NAME, ORIGIN_CODE, ORDER_MEASURE, ATTB1_NM, ATTB2_NM, ATTB3_NM, ATTB4_NM, ATTB5_NM, ATTB6_NM, ATTB7_NM, ATTB8_NM, ATTB9_NM, ATTB10_NM, ATTB11_NM, ATTB12_NM, ATTB13_NM, ATTB14_NM, ATTB15_NM, ATTB16_NM, ATTB17_NM, ATTB18_NM, ATTB19_NM, ATTB20_NM, DELIVERY_LT, ITEM_GUBUN, ITEM_GROUP, ONOFF_TYPE, STD_FLAG, IMG_NO, IMG_FLAG, IMAGE_KEY, REMARK, TO_CHAR (SYSDATE, 'YYYYMMDD') AS ADD_DATE, TO_CHAR (SYSDATE, 'HH24MISS') AS ADD_TIME, #{st_user_id} AS ADD_USER_ID, TO_CHAR (SYSDATE, 'YYYYMMDD') AS CHANGE_DATE, TO_CHAR (SYSDATE, 'HH24MISS') AS CHANGE_TIME, #{st_user_id} AS CHANGE_USER_ID, CMS_PRICE, KEP_DEPT, STOCK_GROUP_TYPE, DETAIL_IMGFILE_NAME, DETAIL_IMGFILE_DIR, IMGFILE_NAME, IMGFILE_DIR, MODEL_INFO FROM CMSCATLG_ADD WHERE SEQ = #{SEQ}


		/*updateTempMasterMdCmStndCatalogReg*/
		UPDATE CMSCATLG_ADD A                        
           SET  DESCRIPTION_LOC = #{DESCRIPTION_LOC}
               ,DESCRIPTION_ENG = #{DESCRIPTION_ENG}
               ,REP_SEPCIFICATION = #{SPECIFICATION}
               ,SPECIFICATION = #{SPECIFICATION}
               ,MAKER_CODE = #{MAKER_CODE}
               ,MAKER_NAME= #{MAKER_NAME}
               ,ORIGIN_CODE = #{ORIGIN_CODE}
               ,ORDER_MEASURE = #{ORDER_MEASURE}
               ,STD_FLAG = #{STD_FLAG}
               ,KEP_DEPT = #{KEP_DEPT}
               ,CMS_CATEG_ID = #{CMS_CATEG_ID}
               ,STOCK_GROUP_TYPE = #{STOCK_GROUP_TYPE}
               ,CHANGE_DATE = TO_CHAR (SYSDATE, 'YYYYMMDD')
               ,CHANGE_TIME = TO_CHAR (SYSDATE, 'HH24MISS')   
               ,CHANGE_USER_ID = #{st_user_id}
               ,DETAIL_IMGFILE_NAME = #{DETAIL_IMGFILE_NAME}
			   ,DETAIL_IMGFILE_DIR = #{DETAIL_IMGFILE_DIR}
			   ,IMGFILE_NAME = #{IMGFILE_NAME}
			   ,IMGFILE_DIR = #{IMGFILE_DIR}        
			   ,MODEL_INFO =#{MODEL_INFO}
			   ,ITEM_GUBUN =#{ITEM_GUBUN}
			   ,SPECIFICATION_ENG =#{SPECIFICATION_ENG}       
         WHERE  A.SEQ=#{SEQ}
